package vn.contractgovernance.api.incident;

import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.obligation.*;
import static vn.contractgovernance.api.obligation.DutyEvidence.id;

@Service
public class IncidentService {
 private final DutyEvidence e;private final LifecycleObligations duties;private final CommandExecutor commands;private final ContractRegistry schemas;private final AuditService audit;private final ListQueries lists;
 public IncidentService(DutyEvidence e,LifecycleObligations duties,CommandExecutor commands,ContractRegistry schemas,AuditService audit,ListQueries lists){this.e=e;this.duties=duties;this.commands=commands;this.schemas=schemas;this.audit=audit;this.lists=lists;}
 public EntityStore.Entity require(UUID id,Actor a){return e.require("Incident",id,a);}
 public JsonNode get(UUID id,Actor a){return project(require(id,a),e.current(a));}
 public JsonNode list(Map<String,String> q,Actor a){a=e.current(a);var args=new ArrayList<Object>();var scope=e.scope(a,args);final Actor actor=a;return lists.page("Incident",a,q,false,scope,args,b->project(new EntityStore.Entity("Incident",id(b,"id"),id(b,"branchId"),b.path("version").asInt(),b),actor));}
 private void createAuth(JsonNode r,Actor a){var c=e.contract(id(r,"contractId"),a);e.maker(new EntityStore.Entity("Incident",UUID.randomUUID(),c.branchId(),1,r),a);}
 public ApiResult create(JsonNode r,String key,Actor a){createAuth(r,a);return commands.execute(a,key,"POST","/api/v1/incidents",r,null,()->createAuth(r,a),()->{var c=e.lockContract(id(r,"contractId"));createAuth(r,a);if(!c.body().hasNonNull("currentVersion"))throw ApiException.of("STATE_CONFLICT","Incident cần phiên bản hợp đồng có hiệu lực/lịch sử thực.");e.nonfuture(r.path("receivedAt"));boolean complaint=r.path("kind").asString().equals("PAYMENT_COMPLAINT_REFERENCE");if(complaint&&(!r.hasNonNull("externalReference")||!r.hasNonNull("externalDueAt")||!r.hasNonNull("externalRuleBasis")))throw ApiException.validation("/externalReference","Complaint cần reference/hạn/basis bên ngoài.");if(r.hasNonNull("externalDueAt")!=r.hasNonNull("externalRuleBasis"))throw ApiException.validation("/externalDueAt","Hạn và basis phải có cặp.");if(r.hasNonNull("externalDueAt")&&Instant.parse(r.path("externalDueAt").asString()).isBefore(Instant.parse(r.path("receivedAt").asString())))throw ApiException.validation("/externalDueAt","Hạn bên ngoài không trước receipt.");if(r.hasNonNull("remediationTrigger")!=r.hasNonNull("durationHours")||(r.hasNonNull("durationHours")&&r.path("durationHours").asInt()!=48))throw ApiException.validation("/durationHours","Chỉ selected demo trigger 48 elapsed hours; null khi không có trigger.");var b=(ObjectNode)e.json.nfc(r);b.put("createdAt",e.now()).put("updatedAt",e.now()).put("branchId",c.branchId().toString()).put("state","OPEN").putNull("obligationId").putNull("externalComplaintConfirmation");for(String f:List.of("allowedActions","blockedActions","resolutionEvidenceFileIds"))b.set(f,e.json.array());b.set("contributorIds",e.json.array().add(a.id().toString()));var incident=e.store.create("Incident",UUID.randomUUID(),c.branchId(),b);var m=e.manifest(incident,e.ids(r.path("receiptEvidenceFileIds")),a,true);var contributors=e.uploaders(m);contributors.add(a.id());e.contribute(incident,b,contributors);incident=e.store.update(incident,b);schemas.validateSchema("Incident",incident.body());var source=e.json.object();source.set("request",r);source.set("contractVersion",c.body().path("currentVersion"));source.set("manifest",m);source.set("contributors",b.path("contributorIds"));e.event(incident,"SOURCE",source,a);audit.record(a,"CREATE",incident,null);return ApiResult.created(project(incident,a),"/api/v1/incidents/"+incident.id());});}
 private void authorize(UUID id,String action,Actor a){var incident=require(id,a);if(action.equals("SUBMIT_RESOLUTION"))e.maker(incident,a);else e.independent(incident,a,"CHECKER");}
 public ApiResult command(UUID id,JsonNode r,String tag,String key,Actor a){String action=r.path("action").asString();authorize(id,action,a);ETags.require(tag);return commands.execute(a,key,"POST","/api/v1/incidents/"+id+"/commands",r,tag,()->authorize(id,action,a),()->{var incident=e.lock("Incident",id);authorize(id,action,a);ETags.check(tag,incident.version());var b=(ObjectNode)incident.body().deepCopy();switch(action){
 case "VERIFY"->{var verifiedAt=e.clock.instant();state(b,"OPEN");var source=e.latest(incident,"SOURCE");verifyManifest(incident,source.path("manifest"),a);var triggerManifest=e.manifest(incident,e.ids(r.path("triggerEvidenceFileIds")),a,true);if(e.uploaders(triggerManifest).contains(a.id()))throw ApiException.of("SOD_VIOLATION","Không tự verify nguồn trigger do mình cung cấp.");e.contribute(incident,b,e.uploaders(triggerManifest));var trigger=b.path("remediationTrigger");Instant triggerAt=null;if(trigger.isNull()){if(r.hasNonNull("triggerAt"))throw ApiException.validation("/triggerAt","Không có trigger thì triggerAt phải null.");}else if(trigger.asString().equals("VERIFICATION_CONFIRMED")){if(r.hasNonNull("triggerAt"))throw ApiException.validation("/triggerAt","Verification trigger dùng server verification time.");triggerAt=verifiedAt;}else{if(!r.hasNonNull("triggerAt"))throw ApiException.validation("/triggerAt","NOTICE_RECEIVED cần actual receipt và selected clause evidence.");e.nonfuture(r.path("triggerAt"));triggerAt=Instant.parse(r.path("triggerAt").asString());}var verified=e.json.object();verified.set("request",r);verified.set("source",source);verified.set("manifest",triggerManifest);verified.put("verifiedAt",JsonSupport.timestamp(verifiedAt));if(triggerAt!=null)verified.put("triggerAt",JsonSupport.timestamp(triggerAt));else verified.putNull("triggerAt");e.event(incident,"VERIFICATION",verified,a);b.put("state","VERIFIED");if(triggerAt!=null){var all=e.contributors(incident);all.addAll(e.uploaders(triggerManifest));var contract=e.store.require("Contract",id(b,"contractId"));UUID duty=duties.remediation(contract,incident,triggerAt,e.json.value(all.stream().map(UUID::toString).toList()));b.put("obligationId",duty.toString()).put("state","REMEDIATION");}}
 case "SUBMIT_RESOLUTION"->{state(b,"VERIFIED","REMEDIATION");var m=e.manifest(incident,e.ids(r.path("evidenceFileIds")),a,true);var contributors=e.uploaders(m);contributors.add(a.id());e.contribute(incident,b,contributors);var candidate=e.json.object();candidate.set("request",r);candidate.set("manifest",m);candidate.set("contributors",b.path("contributorIds"));e.event(incident,"RESOLUTION_CANDIDATE",candidate,a);b.set("resolutionEvidenceFileIds",r.path("evidenceFileIds"));}
 case "RESOLVE"->{state(b,"VERIFIED","REMEDIATION");verifiedSourceGuard(incident,a);resolutionGuard(incident);var candidate=e.latest(incident,"RESOLUTION_CANDIDATE");verifyManifest(incident,candidate.path("manifest"),a);var m=e.manifest(incident,e.ids(r.path("evidenceFileIds")),a,true);if(e.uploaders(m).contains(a.id()))throw ApiException.of("SOD_VIOLATION","Không tự assess nguồn resolution.");if(b.path("kind").asString().equals("PAYMENT_COMPLAINT_REFERENCE")&&!r.hasNonNull("externalComplaintConfirmation"))throw ApiException.of("READINESS_BLOCKED","Cần external complaint confirmation được review độc lập.");e.contribute(incident,b,e.uploaders(m));var assessment=e.json.object();assessment.set("request",r);assessment.set("candidate",candidate);assessment.set("manifest",m);if(r.hasNonNull("externalComplaintConfirmation")){var receipt=e.receipt(incident,r.path("externalComplaintConfirmation"),a,true);if(e.uploaders(receipt).contains(a.id()))throw ApiException.of("SOD_VIOLATION","Không tự assess external complaint proof.");e.contribute(incident,b,e.uploaders(receipt));assessment.set("externalManifest",receipt);}e.event(incident,"RESOLUTION_ACCEPTED",assessment,a);b.set("externalComplaintConfirmation",r.path("externalComplaintConfirmation"));b.put("state","RESOLVED");}
 case "CLOSE"->{state(b,"RESOLVED");verifiedSourceGuard(incident,a);resolutionGuard(incident);var accepted=e.latest(incident,"RESOLUTION_ACCEPTED");verifyManifest(incident,accepted.path("manifest"),a);if(accepted.has("externalManifest"))verifyManifest(incident,accepted.path("externalManifest"),a);verifyManifest(incident,accepted.path("candidate").path("manifest"),a);e.event(incident,"CLOSE",r,a);b.put("state","CLOSED");}
 default->throw ApiException.validation("/action","Không hỗ trợ command.");}b.put("updatedAt",e.now());var updated=e.store.update(incident,b);schemas.validateSchema("Incident",updated.body());audit.record(a,action,updated,r.path("reason").asString());return ApiResult.ok(project(updated,a));});}
 private void verifyManifest(EntityStore.Entity incident,JsonNode m,Actor a){var ids=new TreeSet<UUID>();for(var item:m)ids.add(id(item,"fileId"));if(!e.manifest(incident,ids,a,false).equals(m))throw ApiException.of("STORAGE_INTEGRITY","Nguồn bytes khác lịch sử.");}
 private void resolutionGuard(EntityStore.Entity incident){if(incident.body().hasNonNull("obligationId")){var duty=e.store.lock("Obligation",id(incident.body(),"obligationId"));if(!duty.body().path("state").asString().equals("CLOSED")&&!(duty.body().path("state").asString().equals("CANCELLED")&&duty.body().path("closureOutcome").asString().equals("WAIVED")&&duty.body().hasNonNull("waiverRequest")&&duty.body().path("waiverRequest").path("state").asString().equals("APPROVED")))throw ApiException.of("READINESS_BLOCKED","Linked remediation chưa CLOSED hoặc miễn đúng basis.");}}
 /** Called by Control while owning Contract ancestry locks; no caller-supplied incident list. */
 public void requireResumeAllowed(UUID contract){if(e.store.jdbc().queryForObject("select count(*) from cg_entity where entity_type='Incident' and body->>'contractId'=? and (body->>'blockingResume')::boolean and body->>'state' not in ('RESOLVED','CLOSED')",Long.class,contract.toString())>0)throw ApiException.of("READINESS_BLOCKED","Còn blocking Incident chưa resolved/closed.");}
 public JsonNode project(EntityStore.Entity incident,Actor a){var b=(ObjectNode)incident.body().deepCopy();var actions=e.json.array();var blocked=e.json.array();for(String action:switch(b.path("state").asString()){case "OPEN"->List.of("VERIFY");case "VERIFIED","REMEDIATION"->List.of("SUBMIT_RESOLUTION","RESOLVE");case "RESOLVED"->List.of("CLOSE");default->List.<String>of();})try{authorize(incident.id(),action,a);if(action.equals("VERIFY"))verifyManifest(incident,e.latest(incident,"SOURCE").path("manifest"),a);if(action.equals("RESOLVE")){verifiedSourceGuard(incident,a);resolutionReadGuard(incident);verifyManifest(incident,e.latest(incident,"RESOLUTION_CANDIDATE").path("manifest"),a);}if(action.equals("CLOSE")){verifiedSourceGuard(incident,a);resolutionReadGuard(incident);var accepted=e.latest(incident,"RESOLUTION_ACCEPTED");verifyManifest(incident,accepted.path("manifest"),a);verifyManifest(incident,accepted.path("candidate").path("manifest"),a);if(accepted.has("externalManifest"))verifyManifest(incident,accepted.path("externalManifest"),a);}actions.add(action);}catch(ApiException ex){if(!a.hasRole("AUDITOR"))blocked.add(e.json.object().put("action",action).put("code",ex.code()).put("reason",ex.getMessage()));}if(e.redacted(a)){b.put("summary","[REDACTED]");for(String f:List.of("externalReference","externalRuleBasis"))if(b.hasNonNull(f))b.put(f,"[REDACTED]");if(b.hasNonNull("externalComplaintConfirmation"))((ObjectNode)b.path("externalComplaintConfirmation")).put("basis","[REDACTED]");}b.set("allowedActions",actions);b.set("blockedActions",blocked);return b;}
 private void verifiedSourceGuard(EntityStore.Entity incident,Actor a){verifyManifest(incident,e.latest(incident,"SOURCE").path("manifest"),a);verifyManifest(incident,e.latest(incident,"VERIFICATION").path("manifest"),a);}
 private void resolutionReadGuard(EntityStore.Entity incident){if(incident.body().hasNonNull("obligationId")){var d=e.store.require("Obligation",id(incident.body(),"obligationId"));if(!d.body().path("state").asString().equals("CLOSED")&&!(d.body().path("state").asString().equals("CANCELLED")&&d.body().path("closureOutcome").asString().equals("WAIVED")&&d.body().hasNonNull("waiverRequest")&&d.body().path("waiverRequest").path("state").asString().equals("APPROVED")))throw ApiException.of("READINESS_BLOCKED","Remediation còn mở.");}}
 private void state(JsonNode b,String...states){if(!Set.of(states).contains(b.path("state").asString()))throw ApiException.of("STATE_CONFLICT","Incident không ở trạng thái phù hợp.");}
}
